'use strict';

/**
* Return the index of the first element in a sorted double-precision floating-point strided array which is greater than a specified search element.
*
* @module @stdlib/blas/ext/base/dindex-of-greater-than-sorted
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dindexOfGreaterThanSorted = require( '@stdlib/blas/ext/base/dindex-of-greater-than-sorted' );
*
* var x = new Float64Array( [ 1.0, 2.0, 2.0, 3.0 ] );
*
* var idx = dindexOfGreaterThanSorted( x.length, 2.0, x, 1 );
* // returns 3
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dindexOfGreaterThanSorted = require( '@stdlib/blas/ext/base/dindex-of-greater-than-sorted' );
*
* var x = new Float64Array( [ 1.0, 2.0, 2.0, 3.0 ] );
*
* var idx = dindexOfGreaterThanSorted.ndarray( x.length, 2.0, x, 1, 0 );
* // returns 3
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dindexOfGreaterThanSorted;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dindexOfGreaterThanSorted = main;
} else {
	dindexOfGreaterThanSorted = tmp;
}


// EXPORTS //

module.exports = dindexOfGreaterThanSorted;

// exports: { "ndarray": "dindexOfGreaterThanSorted.ndarray" }
